from pathlib import Path

p=Path('vendor-dashboard.html')
s=p.read_text(encoding='utf-8')

old_city="function orderCity(o){const d=normalizeOrderDetails(o?.details);return d.governorate||d.city||d.province||d.customer_city||o?.city||o?.governorate||'غير محددة'}"
new_city="function orderCity(o){const d=normalizeOrderDetails(o?.details),c=(d.customer&&typeof d.customer==='object')?d.customer:{};return o?.governorate||o?.city||d.governorate||d.city||d.province||d.customer_city||c.governorate||c.city||c.province||'غير محددة'}"
if old_city not in s:
    raise SystemExit('orderCity target not found')
s=s.replace(old_city,new_city,1)

start=s.index('function printShippingLabel(orderId){')
end=s.index('\n\nObject.assign(window',start)
new=r'''function printShippingLabel(orderId){const o=orders.find(x=>String(x.id)===String(orderId));if(!o)return showNotice('تعذر العثور على الطلب للطباعة.',true);const code=o.order_code||String(o.id).slice(0,8),product=orderProductName(o),qty=orderQuantity(o),city=orderCity(o),payment=orderPaymentStatus(o),date=new Date(o.created_at).toLocaleDateString('ar-IQ');const w=window.open('','_blank','width=420,height=360');if(!w)return showNotice('يرجى السماح بالنوافذ المنبثقة لطباعة الملصق.',true);w.document.write(`<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>MeshWar Cargo - ${esc(code)}</title><style>*{box-sizing:border-box}html,body{width:50mm;height:40mm;margin:0;padding:1.5mm;font-family:Arial,sans-serif;color:#000;background:#fff;font-size:8px;overflow:hidden}.label-card{width:100%;height:100%;box-sizing:border-box;border:1px solid #000;padding:2px;display:flex;flex-direction:column;justify-content:space-between;gap:1px;overflow:hidden}.brand{text-align:center;border-bottom:1px solid #000;padding-bottom:1px;line-height:1}.brand h1{margin:0;font-size:10px;font-weight:900}.brand p{margin:1px 0 0;font-size:7px}.order{text-align:center;font-size:10px;font-weight:900;line-height:1;direction:ltr}.barcode{height:22px;min-height:22px;display:flex;align-items:center;justify-content:center;overflow:hidden}.barcode svg{width:100%;max-width:100%;height:22px}.grid{display:grid;grid-template-columns:1fr 1fr;border:1px solid #000;line-height:1.05}.cell{padding:1px 2px;border:1px solid #cbd5e1;min-width:0}.label-title{font-size:7px;color:#475569;margin-bottom:1px}.value{font-size:8px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.product{grid-column:1/-1}.privacy{text-align:center;font-size:7px;color:#475569;border-top:1px dashed #94a3b8;padding-top:1px;line-height:1}@media print{@page{size:50mm 40mm;margin:0}html,body{width:50mm!important;height:40mm!important;margin:0!important;padding:1.5mm!important;box-sizing:border-box;font-size:8px;overflow:hidden}.label-card{width:100%;height:100%;box-sizing:border-box;border:1px solid #000;padding:2px;display:flex;flex-direction:column;justify-content:space-between;page-break-inside:avoid;page-break-after:avoid;break-inside:avoid;overflow:hidden}body{print-color-adjust:exact;-webkit-print-color-adjust:exact}}</style><script src="https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js"><\/script></head><body><div class="label-card"><div class="brand"><h1>MeshWar Cargo</h1><p>ملصق شحن متجر محلي</p></div><div class="order">${esc(code)}</div><div class="barcode"><svg id="barcode"></svg></div><div class="grid"><div class="cell product"><div class="label-title">المنتج</div><div class="value">${esc(product)}</div></div><div class="cell"><div class="label-title">الكمية</div><div class="value">${qty}</div></div><div class="cell"><div class="label-title">التاريخ</div><div class="value">${esc(date)}</div></div><div class="cell"><div class="label-title">المحافظة / المدينة</div><div class="value">${esc(city)}</div></div><div class="cell"><div class="label-title">حالة الدفع</div><div class="value">${esc(payment)}</div></div></div><div class="privacy">MeshWar Cargo</div></div><script>window.addEventListener('load',()=>{try{JsBarcode('#barcode',${JSON.stringify(String(code))},{format:'CODE128',displayValue:false,height:22,margin:0,width:1.25})}catch(e){console.error(e)}setTimeout(()=>window.print(),250)});<\/script></body></html>`);w.document.close()}'''
s=s[:start]+new+s[end:]
p.write_text(s,encoding='utf-8')
